const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const topics = ['자바스크립트', '리액트', 'CSS'];

const Filter = () => {
  const [keyword, setKeyword] = useState('');
  const [level, setLevel] = useState('전체');
  const [picked, setPicked] = useState([]);

  const toggle = (event) => {
    const topic = event.target.name;

    if (event.target.checked) {
      setPicked([...picked, topic]);
    } else {
      setPicked(picked.filter((one) => one !== topic));
    }
  };

  return (
    <div className="form">
      <label className="field" htmlFor="q">코스 검색</label>
      <input className="field__input" id="q" type="search" value={keyword}
        onChange={(event) => setKeyword(event.target.value)} />

      <label className="field" htmlFor="lv">난이도</label>
      <select className="field__select" id="lv" value={level}
        onChange={(event) => setLevel(event.target.value)}>
        <option value="전체">전체</option>
        <option value="입문">입문</option>
        <option value="보통">보통</option>
      </select>

      <div className="checks">
        {topics.map((topic) => (
          <label className="check" key={topic}>
            <input type="checkbox" name={topic}
              checked={picked.includes(topic)} onChange={toggle} />
            {topic}
          </label>
        ))}
      </div>

      <p className="summary">
        {keyword === '' ? '전체' : keyword} · {level} · {picked.length === 0 ? '분야 없음' : picked.join(', ')}
      </p>
    </div>
  );
};

root.render(<Filter />);
